1	// Proprietary in-portal DB manager — query transport to a hosting node's MySQL.
2	//
3	// SECURITY MODEL (read before touching this file):
4	//
5	//   * ISOLATION IS THE MYSQL GRANT, NOT AN APP CHECK. Every query runs
6	//     authenticated as the account's SCOPED manager user (`<username>_mgr`),
7	//     which is granted on `<username>\_%`.* ONLY (see buildDbMgrGrantSql). MySQL
8	//     itself refuses that user any access to another tenant's databases, to the
9	//     `mysql`/`sys`/`performance_schema` system schemas, and — being a db-scoped
10	//     grant — to FILE/PROCESS/SUPER (so no LOAD_FILE / INTO OUTFILE file reads).
11	//     `information_schema` stays readable but MySQL filters its rows to objects
12	//     the connecting user can see, i.e. this account's own databases. The app
13	//     ALSO validates the target db belongs to the account (defence in depth), but
14	//     even a bug there cannot breach the grant.
15	//
16	//   * WHY WE SSH AS ROOT. The account's own OS user is `ForceCommand
17	//     internal-sftp` (SFTP-only — it cannot exec a shell), so we reach the node's
18	//     `mysql` client over the platform's existing root SSH (same credential the
19	//     provisioner uses). Root on the box is NOT root in MySQL here: we pass
20	//     `--user=<mgr>` so the *MySQL* session is the scoped, grant-confined user.
21	//
22	//   * SQL IS NEVER INTERPOLATED INTO A SHELL. The customer's SQL is written to
23	//     the `mysql` process STDIN over the SSH channel — it never appears on the
24	//     command line, so there is no shell-injection surface. The command line
25	//     carries only OUR generated, charset-validated identifiers (db name, mgr
26	//     user) and the mgr password via `MYSQL_PWD` (kept off argv). The whole run
27	//     is wrapped in `timeout` on the node AND a JS-side channel timeout, and the
28	//     output is byte-capped, so a runaway/huge query can't hang or OOM us.
29	//
30	// This module is plain (non-"use server") + synchronous-friendly so the server
31	// actions in lib/actions-hosting-db.ts can call it directly, exactly like
32	// lib/hosting-fs.ts does for the file manager.
33	
34	import { Client } from "ssh2";
35	import { decryptSecret } from "./crypto-box";
36	import { isValidDbIdentifier } from "./hosting";
37	
38	export type DbNodeTarget = {
39	  sshHost: string;
40	  sshPort: number;
41	  rootPassword: string;
42	  mgrUser: string;
43	  mgrPassword: string;
44	};
45	
46	/** Build the transport target for an account: the node's root SSH credential (to
47	 *  reach the `mysql` client) plus the account's scoped manager MySQL credential
48	 *  (what the mysql session actually authenticates as). Returns null until the
49	 *  manager user has been provisioned on the node. Lives in this plain module (not
50	 *  the "use server" actions file) because it is synchronous. */
51	export function dbTargetFor(a: {
52	  node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null };
53	  dbMgrUser: string | null;
54	  dbMgrPassEnc: string | null;
55	}): DbNodeTarget | null {
56	  const rootPassword = a.node.rootPasswordEnc ? decryptSecret(a.node.rootPasswordEnc) : null;
57	  const mgrPassword = a.dbMgrPassEnc ? decryptSecret(a.dbMgrPassEnc) : null;
58	  if (!rootPassword || !a.dbMgrUser || !mgrPassword) return null;
59	  return { sshHost: a.node.sshHost, sshPort: a.node.sshPort, rootPassword, mgrUser: a.dbMgrUser, mgrPassword };
60	}
61	
62	const CONNECT_TIMEOUT_MS = 20_000;
63	/** Hard ceiling on a single query, enforced on BOTH ends: `timeout` on the node
64	 *  kills the mysql process, and the JS timer tears down the SSH channel. */
65	const QUERY_TIMEOUT_S = 15;
66	const QUERY_TIMEOUT_MS = (QUERY_TIMEOUT_S + 5) * 1000;
67	/** Cap the raw bytes we buffer from a result so a `SELECT * FROM huge` can't OOM
68	 *  the app node — we stop reading and mark the result truncated. */
69	const MAX_OUTPUT_BYTES = 2 * 1024 * 1024; // 2 MiB
70	/** Cap on the SQL we will ship to the node (a sane upper bound; the UI edits are
71	 *  tiny and even a pasted query is far under this). */
72	export const MAX_SQL_BYTES = 64 * 1024;
73	
74	export type QueryResult = {
75	  columns: string[];
76	  rows: string[][];
77	  /** true when we stopped at MAX_OUTPUT_BYTES / the row cap and more data exists. */
78	  truncated: boolean;
79	  /** non-null on a MySQL/transport error (already trimmed for display). */
80	  error: string | null;
81	  /** ms the query took end-to-end (for the UI). */
82	  elapsedMs: number;
83	};
84	
85	function connectRoot(t: DbNodeTarget): Promise<Client> {
86	  const conn = new Client();
87	  return new Promise<Client>((resolve, reject) => {
88	    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
89	    conn
90	      .on("ready", () => { clearTimeout(timer); resolve(conn); })
91	      .on("error", (e) => { clearTimeout(timer); reject(e); })
92	      .connect({ host: t.sshHost, port: t.sshPort, username: "root", password: t.rootPassword, readyTimeout: CONNECT_TIMEOUT_MS });
93	  });
94	}
95	
96	/**
97	 * Run one batch of SQL against `dbName` as the scoped manager user and return the
98	 * result set (or an error). The SQL is delivered on the mysql process STDIN, so
99	 * it is opaque to the shell. `--batch --raw` gives us tab-separated output with a
100	 * header row; NULLs come back as the literal `\N`. Non-SELECT statements produce
101	 * no rows (columns empty) — the caller reports a generic success.
102	 */
103	export async function runScopedSql(t: DbNodeTarget, dbName: string, sql: string): Promise<QueryResult> {
104	  const started = Date.now();
105	  // Re-assert the shape of every value that reaches the command line (the caller
106	  // validates too — belt and braces). The mgr user + db name are OUR generated
107	  // identifiers; the password is generated [A-Za-z0-9]. None can carry a shell
108	  // metacharacter, but we verify rather than trust.
109	  if (!isValidDbIdentifier(dbName)) return errResult(started, "invalid database name");
110	  if (!isValidDbIdentifier(t.mgrUser)) return errResult(started, "invalid manager user");
111	  if (!/^[A-Za-z0-9]{1,64}$/.test(t.mgrPassword)) return errResult(started, "invalid manager credential");
112	  const sqlBuf = Buffer.from(String(sql ?? ""), "utf8");
113	  if (sqlBuf.length > MAX_SQL_BYTES) return errResult(started, "query too large");
114	
115	  // `MYSQL_PWD` keeps the password off argv. `timeout` kills a runaway query on
116	  // the node. `--batch` (WITHOUT --raw) gives tab-separated output where mysql
117	  // ESCAPES any tab/newline/backslash inside a value (\t, \n, \\) and prints SQL
118	  // NULL as the sentinel \N — an unambiguous TSV we faithfully unescape on parse.
119	  // The db name is passed as the default schema; the grant is the real boundary.
120	  const cmd =
121	    `MYSQL_PWD='${t.mgrPassword}' timeout ${QUERY_TIMEOUT_S} ` +
122	    `mysql --user='${t.mgrUser}' --batch --default-character-set=utf8mb4 ` +
123	    `--connect-timeout=8 '${dbName}'`;
124	
125	  const conn = await connectRoot(t);
126	  try {
127	    return await new Promise<QueryResult>((resolve) => {
128	      const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } resolve(errResult(started, "query timed out")); }, QUERY_TIMEOUT_MS);
129	      conn.exec(cmd, (err, stream) => {
130	        if (err) { clearTimeout(timer); return resolve(errResult(started, err.message)); }
131	        let out = Buffer.alloc(0);
132	        let errOut = "";
133	        let truncated = false;
134	        stream
135	          .on("close", (code: number) => {
136	            clearTimeout(timer);
137	            if (code && code !== 0) {
138	              // mysql failed (syntax error, access denied, etc.) — surface stderr.
139	              const msg = (errOut || out.toString("utf8")).trim() || `mysql exited ${code}`;
140	              return resolve(errResult(started, msg));
141	            }
142	            const parsed = parseBatchTsv(out.toString("utf8"));
143	            resolve({ columns: parsed.columns, rows: parsed.rows, truncated: truncated || parsed.truncated, error: null, elapsedMs: Date.now() - started });
144	          })
145	          .on("data", (d: Buffer) => {
146	            if (out.length >= MAX_OUTPUT_BYTES) { truncated = true; return; }
147	            out = out.length + d.length > MAX_OUTPUT_BYTES ? Buffer.concat([out, d.subarray(0, MAX_OUTPUT_BYTES - out.length)]) : Buffer.concat([out, d]);
148	            if (out.length >= MAX_OUTPUT_BYTES) truncated = true;
149	          })
150	          .stderr.on("data", (d: Buffer) => { if (errOut.length < 8000) errOut += d.toString(); });
151	        // Deliver the SQL over STDIN, then EOF. Never touches the shell.
152	        stream.end(sqlBuf);
153	      });
154	    });
155	  } finally {
156	    try { conn.end(); } catch { /* */ }
157	  }
158	}
159	
160	function errResult(started: number, message: string): QueryResult {
161	  return { columns: [], rows: [], truncated: false, error: sanitizeError(message), elapsedMs: Date.now() - started };
162	}
163	
164	/** Trim + de-noise a MySQL/transport error for display (drop the leading
165	 *  `ERROR 1064 (42000) at line 1:` prefix mysql prints in batch mode). */
166	export function sanitizeError(message: string): string {
167	  return String(message ?? "")
168	    .replace(/^ERROR\s+\d+\s+\([0-9A-Z]+\)\s+at line \d+:\s*/i, "")
169	    .replace(/^ERROR\s+\d+\s+\([0-9A-Z]+\):\s*/i, "")
170	    .trim()
171	    .slice(0, 500) || "Query failed.";
172	}
173	
174	/** Rows returned by `mysql --batch` cap. We hard-limit rows too so a caller that
175	 *  forgets a LIMIT still can't pull an unbounded set into memory/over the wire. */
176	export const MAX_ROWS = 1000;
177	
178	/** Sentinel a NULL cell resolves to (chosen so it can't collide with a real
179	 *  escaped value; the UI renders it as a muted "NULL"). */
180	export const NULL_CELL = "�NULL�";
181	
182	/** Unescape one `mysql --batch` field: `\N` (whole field) → NULL sentinel, and
183	 *  the in-value escapes `\t` `\n` `\0` `\\` back to their literals. */
184	function unescapeField(f: string): string {
185	  if (f === "\\N") return NULL_CELL;
186	  let out = "";
187	  for (let i = 0; i < f.length; i++) {
188	    if (f[i] === "\\" && i + 1 < f.length) {
189	      const n = f[++i];
190	      out += n === "t" ? "\t" : n === "n" ? "\n" : n === "0" ? "\0" : n === "\\" ? "\\" : n;
191	    } else {
192	      out += f[i];
193	    }
194	  }
195	  return out;
196	}
197	
198	/**
199	 * Parse `mysql --batch` TSV output into columns + rows. Fields are TAB-separated,
200	 * rows newline-separated; mysql escapes any tab/newline/backslash INSIDE a value,
201	 * so splitting on the raw delimiters is unambiguous, then we unescape each field.
202	 */
203	export function parseBatchTsv(text: string): { columns: string[]; rows: string[][]; truncated: boolean } {
204	  if (!text) return { columns: [], rows: [], truncated: false };
205	  const lines = text.replace(/\n$/, "").split("\n");
206	  if (!lines.length || (lines.length === 1 && lines[0] === "")) return { columns: [], rows: [], truncated: false };
207	  const columns = lines[0].split("\t").map(unescapeField);
208	  const rows: string[][] = [];
209	  let truncated = false;
210	  for (let i = 1; i < lines.length; i++) {
211	    if (rows.length >= MAX_ROWS) { truncated = true; break; }
212	    rows.push(lines[i].split("\t").map(unescapeField));
213	  }
214	  return { columns, rows, truncated };
215	}
216	
217	// ---- Safe SQL builders for the browse UI ------------------------------------
218	// The table name here is USER-CHOSEN, so it is NOT sent to any shell — it only
219	// ever lands inside a backtick-quoted identifier in SQL that travels over STDIN.
220	// We (1) accept only a conservative identifier charset, (2) double any backtick,
221	// and (3) the caller additionally checks membership against SHOW TABLES, so a
222	// value can neither break out of the quotes nor name a table the user can't see.
223	
224	const TABLE_IDENT_RE = /^[A-Za-z0-9_$ .-]{1,64}$/;
225	export function isPlausibleTableName(name: string): boolean {
226	  return TABLE_IDENT_RE.test(String(name ?? ""));
227	}
228	
229	/** Quote an identifier for embedding between backticks (double internal ``` ` ```). */
230	export function quoteIdent(name: string): string {
231	  return "`" + String(name).replace(/`/g, "``") + "`";
232	}
233	
234	/** Page size for the row browser (rows per page). */
235	export const BROWSE_PAGE_SIZE = 50;
236	
237	export function showTablesSql(): string {
238	  return "SHOW TABLES;";
239	}
240	
241	/** A bounded page of a table's rows. `offset`/`limit` are clamped to integers by
242	 *  the caller; embedded here as plain numbers (never strings). */
243	export function browseTableSql(table: string, limit: number, offset: number): string {
244	  const lim = Math.max(1, Math.min(BROWSE_PAGE_SIZE, Math.floor(limit)));
245	  const off = Math.max(0, Math.floor(offset));
246	  return `SELECT * FROM ${quoteIdent(table)} LIMIT ${lim} OFFSET ${off};`;
247	}
248	
249	export function countTableSql(table: string): string {
250	  return `SELECT COUNT(*) AS n FROM ${quoteIdent(table)};`;
251	}
