// Proprietary in-portal DB manager — query transport to a hosting node's MySQL.
//
// SECURITY MODEL (read before touching this file):
//
//   * ISOLATION IS THE MYSQL GRANT, NOT AN APP CHECK. Every query runs
//     authenticated as the account's SCOPED manager user (`<username>_mgr`),
//     which is granted on `<username>\_%`.* ONLY (see buildDbMgrGrantSql). MySQL
//     itself refuses that user any access to another tenant's databases, to the
//     `mysql`/`sys`/`performance_schema` system schemas, and — being a db-scoped
//     grant — to FILE/PROCESS/SUPER (so no LOAD_FILE / INTO OUTFILE file reads).
//     `information_schema` stays readable but MySQL filters its rows to objects
//     the connecting user can see, i.e. this account's own databases. The app
//     ALSO validates the target db belongs to the account (defence in depth), but
//     even a bug there cannot breach the grant.
//
//   * PROTOCOL-LEVEL TRANSPORT — NO `mysql` CLI, EVER. The customer's SQL is run
//     through the `mysql2` protocol driver, which speaks the MySQL wire protocol
//     directly. It is NOT a command-line client, so it has NO in-band
//     meta-command interpreter: `\!` (shell-out), `\.`/`source` (read a node
//     file), `\T`/`tee` (write a node file) are CLI-only constructs and are sent
//     verbatim to the server as ordinary (invalid) SQL — they never execute on
//     the node. This is the fix for the mysql-CLI meta-command RCE: there is no
//     client-side interpreter to abuse, and the session authenticates as the
//     scoped `_mgr` user (never root), so the MySQL grant is the sole boundary.
//
//   * WHY WE STILL SSH AS ROOT (BUT ONLY TO TUNNEL). The node's MySQL is bound to
//     localhost and never exposed. We reach it by opening the platform's existing
//     root SSH connection (same credential the provisioner uses) and asking it to
//     `forwardOut` a direct-tcpip channel to 127.0.0.1:3306 on the node. That
//     channel is handed to `mysql2` as its socket. Root SSH is used ONLY as an
//     encrypted tunnel to localhost:3306 — it never runs a shell command and
//     never launches a mysql client, so the tenant's SQL can only ever reach the
//     MySQL server as the scoped, grant-confined user.
//
//   * SQL IS NEVER INTERPOLATED INTO A SHELL, NOR A CLI ARGV. Identifiers we
//     generate (db name, mgr user) are charset-validated; the mgr password is a
//     generated `[A-Za-z0-9]` secret passed only over the authenticated wire
//     handshake. The whole run is byte-capped, row-capped, and bounded by a
//     server-side statement cap AND a JS-side timeout that tears the connection
//     down, so a runaway/huge query can't hang or OOM us.
//
// This module is plain (non-"use server") + synchronous-friendly so the server
// actions in lib/actions-hosting-db.ts can call it directly, exactly like
// lib/hosting-fs.ts does for the file manager.

import { Client, type ClientChannel } from "ssh2";
import mysql from "mysql2/promise";
import { decryptSecret } from "./crypto-box";
import { isValidDbIdentifier } from "./hosting";

export type DbNodeTarget = {
  sshHost: string;
  sshPort: number;
  rootPassword: string;
  mgrUser: string;
  mgrPassword: string;
};

/** Build the transport target for an account: the node's root SSH credential (to
 *  open the tunnel to localhost:3306) plus the account's scoped manager MySQL
 *  credential (what the mysql2 session actually authenticates as). Returns null
 *  until the manager user has been provisioned on the node. Lives in this plain
 *  module (not the "use server" actions file) because it is synchronous. */
export function dbTargetFor(a: {
  node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null };
  dbMgrUser: string | null;
  dbMgrPassEnc: string | null;
}): DbNodeTarget | null {
  const rootPassword = a.node.rootPasswordEnc ? decryptSecret(a.node.rootPasswordEnc) : null;
  const mgrPassword = a.dbMgrPassEnc ? decryptSecret(a.dbMgrPassEnc) : null;
  if (!rootPassword || !a.dbMgrUser || !mgrPassword) return null;
  return { sshHost: a.node.sshHost, sshPort: a.node.sshPort, rootPassword, mgrUser: a.dbMgrUser, mgrPassword };
}

const CONNECT_TIMEOUT_MS = 20_000;
/** Hard ceiling on a single query, enforced on BOTH ends: a server-side statement
 *  cap (max_execution_time / max_statement_time) and a JS timer that destroys the
 *  mysql2 connection + tears down the SSH channel. */
const QUERY_TIMEOUT_S = 15;
const QUERY_TIMEOUT_MS = (QUERY_TIMEOUT_S + 5) * 1000;
/** Cap the bytes we retain from a result so a `SELECT * FROM huge` can't OOM the
 *  app node — we stop reading (destroy the connection) and mark it truncated. */
const MAX_OUTPUT_BYTES = 2 * 1024 * 1024; // 2 MiB
/** Cap on the SQL we will ship to the node (a sane upper bound; the UI edits are
 *  tiny and even a pasted query is far under this). */
export const MAX_SQL_BYTES = 64 * 1024;

export type QueryResult = {
  columns: string[];
  rows: string[][];
  /** true when we stopped at MAX_OUTPUT_BYTES / the row cap and more data exists. */
  truncated: boolean;
  /** non-null on a MySQL/transport error (already trimmed for display). */
  error: string | null;
  /** ms the query took end-to-end (for the UI). */
  elapsedMs: number;
};

function connectRoot(t: DbNodeTarget): Promise<Client> {
  const conn = new Client();
  return new Promise<Client>((resolve, reject) => {
    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
    conn
      .on("ready", () => { clearTimeout(timer); resolve(conn); })
      .on("error", (e) => { clearTimeout(timer); reject(e); })
      .connect({ host: t.sshHost, port: t.sshPort, username: "root", password: t.rootPassword, readyTimeout: CONNECT_TIMEOUT_MS });
  });
}

/** Open a direct-tcpip channel from the root SSH connection to the node's
 *  localhost MySQL. The returned Channel is a duplex stream we hand to mysql2 as
 *  its socket — MySQL stays bound to localhost on the node (never exposed). */
function forwardMysqlChannel(conn: Client): Promise<ClientChannel> {
  return new Promise<ClientChannel>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("SSH tunnel to MySQL timed out")), CONNECT_TIMEOUT_MS);
    conn.forwardOut("127.0.0.1", 0, "127.0.0.1", 3306, (err, channel) => {
      clearTimeout(timer);
      if (err) return reject(err);
      resolve(channel);
    });
  });
}

/**
 * Run one statement of SQL against `dbName` as the scoped manager user and return
 * the result set (or an error). The SQL is executed through the mysql2 protocol
 * driver over an SSH-forwarded channel to the node's localhost MySQL — there is
 * NO mysql CLI in the path, so client-side meta-commands (`\!`, source, tee)
 * cannot execute; they reach the server as ordinary SQL. `multipleStatements` is
 * off, so no stacked queries. Non-SELECT statements produce no rows (columns
 * empty) — the caller reports a generic success.
 */
export async function runScopedSql(t: DbNodeTarget, dbName: string, sql: string): Promise<QueryResult> {
  const started = Date.now();
  // Re-assert the shape of every value we authenticate/connect with (the caller
  // validates too — belt and braces). The mgr user + db name are OUR generated
  // identifiers; the password is generated [A-Za-z0-9].
  if (!isValidDbIdentifier(dbName)) return errResult(started, "invalid database name");
  if (!isValidDbIdentifier(t.mgrUser)) return errResult(started, "invalid manager user");
  if (!/^[A-Za-z0-9]{1,64}$/.test(t.mgrPassword)) return errResult(started, "invalid manager credential");
  const sqlText = String(sql ?? "");
  if (Buffer.byteLength(sqlText, "utf8") > MAX_SQL_BYTES) return errResult(started, "query too large");

  let conn: Client | null = null;
  let channel: ClientChannel | null = null;
  let connection: mysql.Connection | null = null;
  try {
    conn = await connectRoot(t);
    channel = await forwardMysqlChannel(conn);
    // Authenticate as the SCOPED manager user over the forwarded stream. No CLI,
    // no root MySQL session — the grant on `<username>\_%`.* is the only boundary.
    connection = await mysql.createConnection({
      stream: channel,
      user: t.mgrUser,
      password: t.mgrPassword,
      database: dbName,
      multipleStatements: false, // one statement per run — no stacked-query surface
      dateStrings: true,         // DATE/DATETIME/TIMESTAMP as strings (match old display)
      supportBigNumbers: true,
      bigNumberStrings: true,    // no precision loss on BIGINT / DECIMAL
      connectTimeout: CONNECT_TIMEOUT_MS,
      charset: "utf8mb4_general_ci",
    });
    // Best-effort server-side statement cap. MySQL uses max_execution_time (ms,
    // SELECTs only); MariaDB uses max_statement_time (seconds). The value is our
    // own integer constant (no injection surface). Either may be absent — the JS
    // timeout below is the hard guard regardless.
    await connection.query(`SET SESSION max_execution_time = ${QUERY_TIMEOUT_S * 1000}`).catch(() => { /* */ });
    await connection.query(`SET SESSION max_statement_time = ${QUERY_TIMEOUT_S}`).catch(() => { /* */ });

    return await streamQuery(connection, sqlText, started);
  } catch (e) {
    return errResult(started, e instanceof Error ? e.message : String(e));
  } finally {
    // Always tear everything down: mysql2 connection, forwarded channel, SSH.
    try { if (connection) await connection.end(); } catch { try { connection?.destroy(); } catch { /* */ } }
    try { channel?.end(); } catch { /* */ }
    try { conn?.end(); } catch { /* */ }
  }
}

/**
 * Execute one statement via the mysql2 streaming (event-emitter) API on the
 * underlying core connection, enforcing the row + byte caps and a hard JS timeout.
 * Streaming (rather than a buffered `[rows]` await) lets us stop the server mid
 * result-set — destroying the connection — the instant either cap is hit, so a
 * `SELECT * FROM huge` can neither OOM us nor stay on the wire. `rowsAsArray`
 * yields positional arrays that preserve duplicate column names.
 */
function streamQuery(connection: mysql.Connection, sql: string, started: number): Promise<QueryResult> {
  return new Promise<QueryResult>((resolve) => {
    // The promise wrapper exposes the callback-style core connection as `.connection`;
    // only the core connection returns the streaming Query event-emitter.
    const core = (connection as unknown as { connection: any }).connection;
    const columns: string[] = [];
    const rows: string[][] = [];
    let bytes = 0;
    let truncated = false;
    let settled = false;

    const finish = (r: QueryResult) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(r);
    };
    const finishOk = () => finish({ columns, rows, truncated, error: null, elapsedMs: Date.now() - started });
    const stopAtCap = () => {
      truncated = true;
      // Halt further transfer, then resolve with what we have.
      try { core.destroy(); } catch { /* */ }
      finishOk();
    };

    const timer = setTimeout(() => {
      try { core.destroy(); } catch { /* */ }
      finish(errResult(started, "query timed out"));
    }, QUERY_TIMEOUT_MS);

    let q: any;
    try {
      q = core.query({ sql, rowsAsArray: true });
    } catch (e) {
      return finish(errResult(started, e instanceof Error ? e.message : String(e)));
    }
    q.on("error", (err: Error) => finish(errResult(started, err?.message ?? String(err))));
    q.on("fields", (fields: any) => {
      // Emitted once per result set for SELECT-like statements; absent for OK packets.
      if (Array.isArray(fields)) for (const f of fields) columns.push(String(f?.name ?? ""));
    });
    q.on("result", (row: any) => {
      if (settled || truncated) return;
      // Non-SELECT statements emit an OK/result packet (not an array) → no rows.
      if (!Array.isArray(row)) return;
      if (rows.length >= MAX_ROWS) return stopAtCap();
      const out = new Array<string>(row.length);
      for (let i = 0; i < row.length; i++) {
        const s = cellToString(row[i]);
        out[i] = s;
        bytes += Buffer.byteLength(s, "utf8");
      }
      rows.push(out);
      if (bytes >= MAX_OUTPUT_BYTES) return stopAtCap();
    });
    q.on("end", () => finishOk());
  });
}

/** Convert a mysql2 cell value to the display string the UI expects. SQL NULL maps
 *  to the NULL sentinel (the grid renders it as a muted "NULL"); dates already
 *  arrive as strings (dateStrings:true); Buffers are decoded as UTF-8. */
function cellToString(v: unknown): string {
  if (v === null || v === undefined) return NULL_CELL;
  if (typeof v === "string") return v;
  if (Buffer.isBuffer(v)) return v.toString("utf8");
  if (v instanceof Date) return v.toISOString();
  return String(v);
}

function errResult(started: number, message: string): QueryResult {
  return { columns: [], rows: [], truncated: false, error: sanitizeError(message), elapsedMs: Date.now() - started };
}

/** Trim + de-noise a MySQL/transport error for display (drop the leading
 *  `ERROR 1064 (42000) at line 1:` prefix mysql prints in batch mode). */
export function sanitizeError(message: string): string {
  return String(message ?? "")
    .replace(/^ERROR\s+\d+\s+\([0-9A-Z]+\)\s+at line \d+:\s*/i, "")
    .replace(/^ERROR\s+\d+\s+\([0-9A-Z]+\):\s*/i, "")
    .trim()
    .slice(0, 500) || "Query failed.";
}

/** Row cap. We hard-limit rows so a caller that forgets a LIMIT still can't pull
 *  an unbounded set into memory/over the wire. */
export const MAX_ROWS = 1000;

/** Sentinel a NULL cell resolves to (chosen so it can't collide with a real
 *  value; the UI renders it as a muted "NULL"). */
export const NULL_CELL = " NULL ";

// ---- Safe SQL builders for the browse UI ------------------------------------
// The table name here is USER-CHOSEN. MySQL cannot bind an identifier as a
// prepared-statement parameter, so it only ever lands inside a backtick-quoted
// identifier in SQL that travels over the mysql2 wire (never a shell, never a
// CLI argv). We (1) accept only a conservative identifier charset, (2) double any
// backtick, and (3) the caller additionally checks membership against SHOW TABLES,
// so a value can neither break out of the quotes nor name a table the user can't
// see. LIMIT/OFFSET are integer-clamped and embedded as plain numbers.

const TABLE_IDENT_RE = /^[A-Za-z0-9_$ .-]{1,64}$/;
export function isPlausibleTableName(name: string): boolean {
  return TABLE_IDENT_RE.test(String(name ?? ""));
}

/** Quote an identifier for embedding between backticks (double internal ``` ` ```). */
export function quoteIdent(name: string): string {
  return "`" + String(name).replace(/`/g, "``") + "`";
}

/** Page size for the row browser (rows per page). */
export const BROWSE_PAGE_SIZE = 50;

export function showTablesSql(): string {
  return "SHOW TABLES;";
}

/** A bounded page of a table's rows. `offset`/`limit` are clamped to integers by
 *  the caller; embedded here as plain numbers (never strings). */
export function browseTableSql(table: string, limit: number, offset: number): string {
  const lim = Math.max(1, Math.min(BROWSE_PAGE_SIZE, Math.floor(limit)));
  const off = Math.max(0, Math.floor(offset));
  return `SELECT * FROM ${quoteIdent(table)} LIMIT ${lim} OFFSET ${off};`;
}

export function countTableSql(table: string): string {
  return `SELECT COUNT(*) AS n FROM ${quoteIdent(table)};`;
}
